ALTER TABLE public.ap_anticipation ADD CONSTRAINT ap_simulation_values_valid CHECK (status IS NULL OR (data_antecipacao IS NOT NULL AND created_by IS NOT NULL AND anticipated_amount > 0 AND valor_descontado IS NOT NULL AND valor_descontado >= 0 AND valor_liquido IS NOT NULL AND valor_liquido > 0 AND valor_liquido <= anticipated_amount AND anticipated_amount::text NOT IN ('NaN','Infinity','-Infinity') AND valor_liquido::text NOT IN ('NaN','Infinity','-Infinity') AND valor_descontado::text NOT IN ('NaN','Infinity','-Infinity')));
